import{_ as a,o as h,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2016 Ceph社区年度进展报告","description":"","frontmatter":{"title":"2016 Ceph社区年度进展报告","date":"2016-12-01T00:00:00.000Z","updated":"2016-12-01T00:00:00.000Z","tags":["Ceph","社区动态","年度报告"],"categories":["年度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016_Ceph社区年度总结.md","filePath":"posts/2016/2016_Ceph社区年度总结.md","lastUpdated":1780460162000}'),l={name:"posts/2016/2016_Ceph社区年度总结.md"};function t(p,e,s,_,i,n){return h(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ceph-社区-2016-年度进展报告" tabindex="-1">Ceph 社区 2016 年度进展报告 <a class="header-anchor" href="#ceph-社区-2016-年度进展报告" aria-label="Permalink to &quot;Ceph 社区 2016 年度进展报告&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>2016 年是 Ceph 项目承上启下的关键一年。社区在这一年完成了 Jewel 版本的发布，并全力推进 Kraken 和 Luminous 的开发准备工作。BlueStore 从实验性功能走向候选默认后端，Messenger v2 协议设计成型，Manager 守护进程架构初现雏形——这些技术方向共同构成了 Ceph 下一阶段演进的基础。</p><hr><h2 id="一、全年技术演进" tabindex="-1">一、全年技术演进 <a class="header-anchor" href="#一、全年技术演进" aria-label="Permalink to &quot;一、全年技术演进&quot;">​</a></h2><h3 id="存储后端革新-filestore-→-bluestore" tabindex="-1">存储后端革新：FileStore → BlueStore <a class="header-anchor" href="#存储后端革新-filestore-→-bluestore" aria-label="Permalink to &quot;存储后端革新：FileStore → BlueStore&quot;">​</a></h3><p>2016 年最重要的技术方向是彻底替换 OSD 存储后端。传统 FileStore 依赖 POSIX 文件系统，存在双重日志开销、原子性不足等固有缺陷。<a href="./2016-JUN-21_--_Ceph_TechTalks_-_Bluestore.html">2016-JUN-21 的 Tech Talk</a> 系统介绍了 BlueStore 的设计哲学：绕过文件系统，直接管理裸块设备，以 RocksDB 存储元数据，对象数据直写块设备，从而获得原子性事务、高效对象枚举、内联压缩和 checksum 等能力。</p><p><a href="/VideoSummary/posts/2016/2016-JUN-01_--_Ceph_Developer_Monthly.html">2016-JUN-01 的开发者月度会议</a>) 进一步确定了 BlueStore 缓存的关键设计决策：采用分片缓存结构（Sharded Cache）和 MultiQ 缓存替换算法，以提升多核并发性能并减少锁竞争。<a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 的开发者月度会议</a>) 则展示了 BlueStore onode 序列化的持续优化，通过引入标志位和优化物理扩展引用来降低 CPU 开销。</p><h3 id="网络层重构-messenger-v2" tabindex="-1">网络层重构：Messenger v2 <a class="header-anchor" href="#网络层重构-messenger-v2" aria-label="Permalink to &quot;网络层重构：Messenger v2&quot;">​</a></h3><p>网络协议的现代化是 2016 年另一条主线。<a href="/VideoSummary/posts/2016/2016-MAR-02_-_-_Ceph_Developer_Monthly.html">2016-MAR-02 的开发者月度会议</a>) 讨论了新的同步消息协议设计，重点关注与 DPDK、liburing 的集成以实现高性能网络通信，以及多 OSD 宿主机场景下的锁竞争优化。<a href="/VideoSummary/posts/2016/2016-JUN-01_--_Ceph_Developer_Monthly.html">2016-JUN-01 的会议</a>) 进一步讨论了 Messenger v2 的安全设计，包括防降级攻击、消息头签名、客户端与服务端协议版本协商机制。网络加密需求也在 <a href="/VideoSummary/posts/2016/2016-MAR-02_-_-_Ceph_Developer_Monthly.html">3 月的会议</a>) 中被提出，建议利用处理器硬件加速降低加密开销。</p><h3 id="manager-守护进程架构" tabindex="-1">Manager 守护进程架构 <a class="header-anchor" href="#manager-守护进程架构" aria-label="Permalink to &quot;Manager 守护进程架构&quot;">​</a></h3><p><a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 的会议</a>) 明确了 Manager（ceph-mgr）的定位：作为可选组件承接 Monitor 的部分职责，首要任务是将 PG 状态和统计信息从 Monitor 迁移至 Manager，计划在 Luminous 版本完成，Kraken 版本提供实验性支持。这一架构变化对于解决 Monitor 在大规模集群下的性能瓶颈具有重要意义。</p><hr><h2 id="二、重大里程碑" tabindex="-1">二、重大里程碑 <a class="header-anchor" href="#二、重大里程碑" aria-label="Permalink to &quot;二、重大里程碑&quot;">​</a></h2><h3 id="jewel-版本发布" tabindex="-1">Jewel 版本发布 <a class="header-anchor" href="#jewel-版本发布" aria-label="Permalink to &quot;Jewel 版本发布&quot;">​</a></h3><p>Jewel（v10.2.x）是 2016 年上半年的核心交付目标。<a href="/VideoSummary/posts/2016/2016-FEB-25_--_Ceph_Tech_Talks_-_CephFS.html">2016-FEB-25 的 CephFS Tech Talk</a>) 明确指出该次分享是&quot;Jewel 最后一个重要更新前的介绍&quot;，说明 Jewel 在 2016 年上半年已进入收尾阶段。Jewel 是 Ceph 历史上第一个将 CephFS 标记为生产就绪的版本，具有里程碑意义。</p><h3 id="kraken-与-luminous-的开发准备" tabindex="-1">Kraken 与 Luminous 的开发准备 <a class="header-anchor" href="#kraken-与-luminous-的开发准备" aria-label="Permalink to &quot;Kraken 与 Luminous 的开发准备&quot;">​</a></h3><p><a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 的会议</a>) 多次提及&quot;Kraken 版本&quot;和&quot;Luminous 版本&quot;的规划，包括 Manager 实验性支持进入 Kraken、PG 状态迁移在 Luminous 完成、BlueStore 成为 Kraken 默认后端等目标，显示社区已在年中开始为后续两个版本做系统性准备。</p><h3 id="ci-cd-基础设施统一化" tabindex="-1">CI/CD 基础设施统一化 <a class="header-anchor" href="#ci-cd-基础设施统一化" aria-label="Permalink to &quot;CI/CD 基础设施统一化&quot;">​</a></h3><p><a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">2016-AUG-25 的 Tech Talk</a>) 专题讨论了构建和发布流程的现代化改造，引入 Docker 容器化构建环境、Kubernetes 弹性扩展、Nexus/Artifactory 依赖管理等方案，标志着 Ceph 社区工程基础设施进入系统性升级阶段。</p><hr><h2 id="三、核心组件进展" tabindex="-1">三、核心组件进展 <a class="header-anchor" href="#三、核心组件进展" aria-label="Permalink to &quot;三、核心组件进展&quot;">​</a></h2><h3 id="bluestore" tabindex="-1">BlueStore <a class="header-anchor" href="#bluestore" aria-label="Permalink to &quot;BlueStore&quot;">​</a></h3><p>全年进展最为显著的组件。从 <a href="/VideoSummary/posts/2016/2016-JUN-21_--_Ceph_Tech_Talks_-_Bluestore.html">6 月的架构介绍</a>) 到 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">8 月的序列化优化</a>)，再到 <a href="/VideoSummary/posts/2016/2016-JUN-01_--_Ceph_Developer_Monthly.html">6 月开发者会议</a>) 确定的缓存架构，BlueStore 在 2016 年完成了从概念验证到工程落地的关键跨越。年底规划中已明确将其作为 Kraken 的候选默认后端，并列出了后续路线：支持 SPDK 优化 NVMe 性能、SMR 硬盘支持、ZetaScale 作为 RocksDB 替代方案等。</p><h3 id="cephfs" tabindex="-1">CephFS <a class="header-anchor" href="#cephfs" aria-label="Permalink to &quot;CephFS&quot;">​</a></h3><p><a href="/VideoSummary/posts/2016/2016-FEB-25_--_Ceph_Tech_Talks_-_CephFS.html">2016-FEB-25 的 Tech Talk</a>) 展示了 Jewel 周期内 CephFS 的主要新特性：文件系统 scrub 和修复工具（用于检测元数据损坏）、改进的细粒度授权控制、支持将文件指向特定 RADOS 命名空间的文件布局改进、以及多文件系统支持（单集群内创建多个独立文件系统）。与 OpenStack Manila 的集成也在持续推进。</p><p><a href="./2016-AUG-03_-_Ceph_Developer_Monthly.html">2016-AUG-03 的会议</a> 介绍了 MDS 元数据负载均衡器 Mantle 的设计，通过 Lua 脚本注入实现策略与机制分离，允许灵活调整负载均衡策略，但彼时仍处于实验阶段。</p><h3 id="rbd" tabindex="-1">RBD <a class="header-anchor" href="#rbd" aria-label="Permalink to &quot;RBD&quot;">​</a></h3><p>RBD 在 2016 年有两个重要方向：</p><ul><li><strong>镜像横向扩展</strong>：<a href="./2016-AUG-03_-_Ceph_Developer_Monthly.html">2016-AUG-03 的会议</a> 介绍了三阶段方案，从活动/被动故障转移，到每镜像横向扩展（RPC 消息分配），再到基于指标的热点能力扩展。</li><li><strong>客户端持久缓存</strong>：同次会议介绍了将读写负载从集群卸载到本地缓存的设计，支持克隆镜像的共享读缓存，使用稀疏文件或 BlueStore 实例存储缓存数据。</li></ul><p><a href="./2016-SEP-07_-_Ceph_Developer_Monthly.html">2016-SEP-07 的开发者月度会议</a> 讨论了 RBD 快照和一致性组的设计，包括快照类型字段区分用户快照与一致性组快照、并行创建快照的内部机制等。</p><h3 id="rgw" tabindex="-1">RGW <a class="header-anchor" href="#rgw" aria-label="Permalink to &quot;RGW&quot;">​</a></h3><p>2016 年的会议材料中 RGW 专项讨论相对较少，但 <a href="/VideoSummary/posts/2016/Ceph_Promo_Video.html">Ceph 宣传视频</a>) 中强调了对象存储作为 Ceph 三大接口之一的核心地位，CRUSH 算法和无单点故障架构是 RGW 可靠性的基础。</p><h3 id="qos-与内存管理" tabindex="-1">QoS 与内存管理 <a class="header-anchor" href="#qos-与内存管理" aria-label="Permalink to &quot;QoS 与内存管理&quot;">​</a></h3><p><a href="./2016-OCT-05_-_Ceph_Developer_Monthly.html">2016-OCT-05 的开发者月度会议</a> 讨论了两个底层基础设施改进：一是基于 DM Block算法的 QoS 实现，重点区分背景 I/O（恢复、scrub）与客户端 I/O；二是新的内存池分配器，通过宏定义实现对象在正确内存池中的分配，解决内存碎片化问题，并支持编译时调试模式追踪对象分配。</p><h3 id="安全性" tabindex="-1">安全性 <a class="header-anchor" href="#安全性" aria-label="Permalink to &quot;安全性&quot;">​</a></h3><p><a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 的会议</a>) 讨论了 Kerberos 认证集成方案，定义新认证类型直接与 libkrb5 交互，并探讨了&quot;混合令牌&quot;机制将用户身份与 Ceph 身份结合。同次会议还讨论了 EC 库中 SIMD 指令集检测的实现，以支持不同处理器架构的性能优化。</p><h3 id="dashboard-管理工具" tabindex="-1">Dashboard /管理工具 <a class="header-anchor" href="#dashboard-管理工具" aria-label="Permalink to &quot;Dashboard /管理工具&quot;">​</a></h3><p><a href="./2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATIC.html">2016-JUN-23 的 Tech Talk</a> 介绍了 OpenATIC 与 Ceph 的深度集成进展，包括基于 Librados 和 LibRBD API 的集群管理、Nagios+RDtool 监控、Saltstack 远程节点管理，以及新的 Ceph 管理仪表板开发计划。OpenATTIC 每月发布新版本，是当时 Ceph 管理界面的重要社区方案。</p><hr><h2 id="四、社区生态" tabindex="-1">四、社区生态 <a class="header-anchor" href="#四、社区生态" aria-label="Permalink to &quot;四、社区生态&quot;">​</a></h2><h3 id="工程基础设施建设" tabindex="-1">工程基础设施建设 <a class="header-anchor" href="#工程基础设施建设" aria-label="Permalink to &quot;工程基础设施建设&quot;">​</a></h3><p>2016 年社区在工程效率上投入显著。<a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">统一 CI 的 Tech Talk</a>) 反映了随着贡献者数量增长，原有 Jenkins 构建系统已难以支撑，社区开始系统性地引入容器化和云原生工具链来提升 CI/CD 能力。<a href="/VideoSummary/posts/2016/2016-MAR-02_-_-_Ceph_Developer_Monthly.html">3 月的开发者会议</a>) 也讨论了 Teuthology（Paddle/Pulpito）测试基础设施的改进，包括为测试结果添加问题追踪字段、支持按 SHA 和作业描述查询等。</p><h3 id="基准测试工具" tabindex="-1">基准测试工具 <a class="header-anchor" href="#基准测试工具" aria-label="Permalink to &quot;基准测试工具&quot;">​</a></h3><p><a href="/VideoSummary/posts/2016/2016-MAY-26_--_Ceph_Tech_Talks_-_Ceph_Benchmarking_Tool.html">2016-MAY-26 的 Tech Talk</a>) 专题介绍了 CBT（Ceph Benchmarking Tool），这一由 Mark Nelson 开发的 Python 框架已成为社区标准基准测试工具，支持 RBD、文件系统、对象存储的全面测试，并提供自动化集群配置和结果收集能力。</p><h3 id="企业用户实践" tabindex="-1">企业用户实践 <a class="header-anchor" href="#企业用户实践" aria-label="Permalink to &quot;企业用户实践&quot;">​</a></h3><p><a href="./2016-JAN-26_--_Ceph_Tech_Talks_-_High-Performance_Production_Databaseson_Ceph.html">2016-JAN-26 的 Tech Talk</a> 展示了 Medalia 公司将 Ceph 用于高性能生产数据库的实践，结合 Docker 容器化和 OpenStack 编排，实现了单流 I/O 550 MB/s、多流接近 4 GB/s 的性能指标，为社区提供了企业级落地的参考案例。</p><h3 id="hackathon-与社区活动" tabindex="-1">Hackathon 与社区活动 <a class="header-anchor" href="#hackathon-与社区活动" aria-label="Permalink to &quot;Hackathon 与社区活动&quot;">​</a></h3><p><a href="/VideoSummary/posts/2016/2016-MAR-02_-_-_Ceph_Developer_Monthly.html">2016-MAR-02 的会议</a>) 提及了 Ceph Hackathon 的筹备，Sage 负责收集主题建议，显示社区在线下协作活动上保持活跃。Google Summer of Code 也被提及作为网络加密等新特性的孵化渠道。</p><hr><h2 id="五、下一年展望" tabindex="-1">五、下一年展望 <a class="header-anchor" href="#五、下一年展望" aria-label="Permalink to &quot;五、下一年展望&quot;">​</a></h2><p>基于 2016 年的技术讨论和规划，可以推断 2017 年社区将重点推进以下方向：</p><p><strong>BlueStore 成为默认后端</strong>：Kraken 版本将 BlueStore 作为候选默认后端，2017 年的 Luminous 版本预计完成这一切换，同时推进 SPDK 支持以充分发挥 NVMe 设备性能。</p><p><strong>Manager 守护进程正式化</strong>：PG 状态从 Monitor 迁移至 Manager 是 Luminous 的核心目标，这将显著改善大规模集群的 Monitor 压力，并为后续的模块化管理能力（如 Dashboard、Prometheus 导出）奠定基础。</p><p><strong>Messenger v2 落地</strong>：网络协议现代化工作将在 2017 年进入实现阶段，带来加密支持、更好的多连接管理和性能提升。</p><p><strong>CephFS 生产化深化</strong>：多文件系统、Mantle 负载均衡器、与 Manila 集成等特性将持续完善，推动 CephFS 在更多生产场景落地。</p><p><strong>QoS 与性能隔离</strong>：DM Block 算法的 QoS 实现将为混合负载场景（客户端 I/O 与后台恢复并存）提供更好的服务质量保障。</p><p><strong>管理工具整合</strong>：OpenATTIC 与 Ceph 的深度集成，以及 Manager 模块化架构，预示着 Ceph 原生 Dashboard 将在 Luminous 周期内成为重要交付目标。</p><hr><p><em>本报告基于 2016 年 12 篇社区会议和技术分享的内容整理，涵盖开发者月度会议（CDM）和 Ceph Tech Talks 两个主要系列。</em></p><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">2016-AUG-25 -- Ceph Tech Talk: Unified CI</a>)</li><li><a href="/VideoSummary/posts/2016/2016-FEB-25_--_Ceph_Tech_Talks_-_CephFS.html">2016-FEB-25 -- Ceph Tech Talks: CephFS</a>)</li><li><a href="/VideoSummary/posts/2016/2016-JAN-26_--_Ceph_Tech_Talks_-_High-Performance_Production_Databases_on_Ceph.html">2016-JAN-26 -- Ceph Tech Talks: High-Performance Production Databases on Ceph</a>)</li><li><a href="/VideoSummary/posts/2016/2016-JUN-01_--_Ceph_Developer_Monthly.html">2016-JUN-01 -- Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2016/2016-JUN-21_--_Ceph_Tech_Talks_-_Bluestore.html">2016-JUN-21 -- Ceph Tech Talks: Bluestore</a>)</li><li><a href="/VideoSummary/posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.html">2016-JUN-23 -- Ceph Tech Talks: OpenATTIC</a>)</li><li><a href="/VideoSummary/posts/2016/2016-MAR-02_-_-_Ceph_Developer_Monthly.html">2016-MAR-02 -- Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2016/2016-MAY-26_--_Ceph_Tech_Talks_-_Ceph_Benchmarking_Tool.html">2016-MAY-26 -- Ceph Tech Talks: Ceph Benchmarking Tool</a>)</li><li><a href="/VideoSummary/posts/2016/2016-OCT-05_-_-_Ceph_Developer_Monthly.html">2016-OCT-05 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2016/Ceph_Promo_Video.html">Ceph promo Video</a>)</li></ul>',63)])])}const d=a(l,[["render",t]]);export{u as __pageData,d as default};
